  ((select id from w), 'multiple_choice', 'According to 1 Samuel 16:7, what does Yahweh say he looks at, in contrast to outward appearance?', '1 Samuel 16:7', 'Don''t look on his face, or on the height of his stature, because I have rejected him; for I don''t see as man sees. For man looks at the outward appearance, but Yahweh looks at the heart.', 'WEB', 2,
