  ((select id from w), 'recall', 'Fill in the missing word: whose soul was knit with David''s soul, per 1 Samuel 18:1?', '1 Samuel 18:1', 'When he had finished speaking to Saul, the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.', 'WEB', 2,
