  ((select id from w), 'recall', 'Fill in the missing word: what did Nathan say Yahweh had put away, after David confessed?', '2 Samuel 12:13', 'David said to Nathan, ''I have sinned against Yahweh.'' Nathan said to David, ''Yahweh also has put away your sin. You will not die.''', 'WEB', 2,
