  ((select id from w), 'recall', 'Fill in the missing word: what did David tell his servants Absalom would strike the city with, if they didn''t flee?', '2 Samuel 15:14', 'David said to all his servants who were with him at Jerusalem, ''Arise! Let''s flee, or else none of us will escape from Absalom. Hurry to depart, lest he overtake us quickly and bring down evil on us, and strike the city with the edge of the sword.''', 'WEB', 2,
